    # Check if all song_ids are in downloaded_songs
    downloaded_ids = {s['song_id'] for s in downloaded_songs}
    if all(sid in downloaded_ids for sid in song_ids):
        # Sum durations of those songs
        total_duration = sum(s['duration'] for s in downloaded_songs if s['song_id'] in song_ids)
        if total_duration >= 900:
            selected_album = album
            print(f"Selected album: {album['title']} (id={album['album_id']}), total duration={total_duration} sec")
            break

